const boxes = buildNameBoxes\(meta, roi, ref, { style: "tight" }\);
const textImg = sharp\(abs\).extract\(boxes.text\);
const lineImg = sharp\(abs\).extract\(boxes.textLine\);
const buffers = [
  await preprocessForOcr\(sharp\(abs\).extract\(boxes.name\), { width: 2200 }\),
  await preprocessRawForOcr\(sharp\(abs\).extract\(boxes.name\), { width: 2200 }\),
  await preprocessForOcr\(sharp\(abs\).extract\(boxes.name\), { width: 2200, threshold: 145 }\),
