  await preprocessForOcr\(sharp\(abs\).extract\(boxes.text\), { width: 2200, threshold: 145 }\),
  await preprocessForOcr\(lineImg, { width: 2400 }\),
  await preprocessForOcr\(lineImg, { width: 2400, threshold: 140 }\),
];
